int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret = 0;
    struct address_space *mapping = NULL;

    if (!inode || !bh || !next_pgofs) {
        return -EINVAL;
    }

    mapping = inode->i_mapping;
    if (!mapping) {
        return -EINVAL;
    }

    ret = mapping->a_ops->bmap(mapping, iblock, bh, create, flag, next_pgofs);
    if (ret < 0) {
        return ret;
    }

    if (!bh->b_blocknr) {
        return -EIO;
    }

    return 0;
}
